// ── Set timezone to India Standard Time (IST) ──────────────────
date_default_timezone_set('Asia/Kolkata');

// ── Error handling: suppress display, log to file ──────────────

ini_set('display_errors', '0');
ini_set('log_errors', '1');
error_reporting(E_ALL);

// ── Load config + auth ─────────────────────────────────────────
require_once __DIR__ . '/config/db.php';
require_once __DIR__ . '/includes/auth.php';

requireLogin();
$user = currentUser();
if (!$user) { doLogout(); header('Location: /auth/login.php'); exit; }

// ── Effective per-role/tenant permission map (plan ceiling × role toggle) ──
// Drives which sidebar menu items are shown. See includes/auth.php.
$perms = getEffectivePermissions($user['tenant_id'] ?? null, $user['role'] ?? 'viewer');

// ── Recent login/logout activity (Profile → Activity Timeline card) ──
$loginActivity = getRecentLoginActivity((int)$user['id'], 20);
function optms_time_ago(string $datetime): string {
    $diff = time() - strtotime($datetime);
    if ($diff < 60)     return 'Just now';
    if ($diff < 3600)   return floor($diff/60) . ' min ago';
    if ($diff < 86400)  return floor($diff/3600) . ' hr ago';
    if ($diff < 604800) { $d = floor($diff/86400); return $d . ' day' . ($d > 1 ? 's' : '') . ' ago'; }
    return date('d M Y, h:i A', strtotime($datetime));
}

// ── Identity badges (topbar + dashboard): firm name + role ──────
$ROLE_BADGE_COLORS = [
    'owner'       => ['bg' => '#E0F2F1', 'text' => '#00695C'],
    'admin'       => ['bg' => '#FFF8E1', 'text' => '#F57F17'],
    'manager'     => ['bg' => '#E3F2FD', 'text' => '#1565C0'],
    'accountant'  => ['bg' => '#E8F5E9', 'text' => '#2E7D32'],
    'sales'       => ['bg' => '#F3E5F5', 'text' => '#7B1FA2'],
    'viewer'      => ['bg' => '#F5F5F5', 'text' => '#616161'],
    'super_admin' => ['bg' => '#FFEBEE', 'text' => '#C62828'],
];
$userRole      = $user['role'] ?? 'viewer';
$isSuperAdmin  = $userRole === 'super_admin';
$roleBadgeCol  = $ROLE_BADGE_COLORS[$userRole] ?? ['bg' => '#F5F5F5', 'text' => '#616161'];
$roleBadgeLabel= $isSuperAdmin ? 'Super Admin' : ucfirst($userRole);

// Adjust this if your super-admin panel lives at a different path.
define('ADMIN_PANEL_URL', '/admin/');

$hourNow  = (int)date('G');
$greeting = $hourNow < 12 ? 'Good morning' : ($hourNow < 17 ? 'Good afternoon' : 'Good evening');

// ── Load company settings ──────────────────────────────────────
$settings = [];
try {
    $db   = getDB();
    $rows = $db->query('SELECT `key`, value FROM settings')->fetchAll();
    foreach ($rows as $r) $settings[$r['key']] = $r['value'];
} catch (Exception $e) {
    error_log('Settings load error: ' . $e->getMessage());
}
$firmName = $user['company_name'] ?? ($settings['company_name'] ?? 'OPTMS Tech'); // re-resolve now settings are loaded

$companyName    = $settings['company_name']     ?? 'OPTMS Tech';
$prefix         = $settings['invoice_prefix']   ?? 'OT-' . date('Y') . '-';
$estPrefix      = $settings['estimate_prefix']  ?? 'QT-' . date('Y') . '-';
$companyGst     = $settings['company_gst']      ?? '';
$companyPhone   = $settings['company_phone']    ?? '';
$companyEmail   = $settings['company_email']    ?? '';
$companyWebsite = $settings['company_website']  ?? '';
$companyUpi     = $settings['company_upi']      ?? '';
$companyAddress = $settings['company_address']  ?? '';
$companyLogo    = $settings['company_logo']     ?? '';
$companySign    = $settings['company_sign']     ?? '';
$companyBank    = $settings['company_bank']     ?? '';
$defaultGst     = $settings['default_gst']      ?? '';
$dueDays        = $settings['due_days']         ?? '';
$activeTemplate = $settings['active_template']  ?? '';
$defaultTnc     = $settings['default_tnc']      ?? '';
$defaultCurrency= $settings['default_currency'] ?? '₹';
$businessType   = $settings['business_type']    ?? 'both';
