      .wa-log-table th {
        padding: 10px 14px; text-align: left; font-weight: 700;
        color: var(--muted); font-size: 11px; text-transform: uppercase;
        letter-spacing: .5px;
      }
      .wa-log-table td { padding: 10px 14px; border-bottom: 1px solid var(--border); color: var(--text); }
