// UTILS
// ══════════════════════════════════════════
function getInitials(name) {
  const words = (name||'').split(/\s+/).filter(Boolean);
  if (words.length >= 2) return (words[0][0] + words[words.length-1][0]).toUpperCase();
  return (name||'?').slice(0,2).toUpperCase();
}


