      };
      // Restore TPL_CUSTOM from PHP-bridge settings (runs synchronously before DOM ready)
      if (window.TPL_CUSTOM) {
        if (s.tpl_color1)        TPL_CUSTOM.color1        = s.tpl_color1;
        if (s.tpl_color2)        TPL_CUSTOM.color2        = s.tpl_color2;
