        email_cc_self:    s.email_cc_self    || '0',
        // ── Automation toggles — must be loaded from DB not hardcoded ──
        email_auto_inv:      s.email_auto_inv      ?? '0',
        email_auto_est:      s.email_auto_est      ?? '0',
        email_auto_paid:     s.email_auto_paid     ?? '1',
